test.describe('REQ-4-2-2 error values, isolation and recovery', () => {
  test('shows error values, keeps the raw formula, does not block other cells, and survives reload', async ({
    page,
  }) => {
    await createWorkbook(page, 'C error values');
    await editCell(page, 'A1', '2');
    await editCell(page, 'B1', '=1/0');
    await editCell(page, 'C1', '=FOO(1)');
    await editCell(page, 'D1', '=(1+2');
    await expectCellText(page, 'B1', '#DIV/0!');
    await expectCellText(page, 'C1', '#NAME?');
    await expectCellText(page, 'D1', '#ERROR!');
    await expectFormulaBar(page, 'B1', '=1/0');
    await expectFormulaBar(page, 'C1', '=FOO(1)');

    // An error cell does not stop other cells from being edited or calculated.
    await typeFormulaBar(page, 'E1', '=A1+1');
    await expectCellText(page, 'E1', '3');

    // Fixing the error removes it and updates dependents.
    await editCell(page, 'B1', '=1+1');
    await expectCellText(page, 'B1', '2');

    await page.reload();
    await expect(page.getByRole('grid', { name: 'Worksheet grid' })).toBeVisible();
    await expectCellText(page, 'B1', '2');
    await expectCellText(page, 'C1', '#NAME?');
    await expectCellText(page, 'D1', '#ERROR!');
    await expectFormulaBar(page, 'C1', '=FOO(1)');
  });

  test('marks a cyclic pair as #REF! and recovers when the cycle is broken', async ({ page }) => {
    await createWorkbook(page, 'C cycle recovery');
    await editCell(page, 'A1', '=B1');
    await editCell(page, 'B1', '=A1');
    await expectCellText(page, 'A1', '#REF!');
    await expectCellText(page, 'B1', '#REF!');

    await editCell(page, 'B1', '3');
    await expectCellText(page, 'A1', '3');
    await expectCellText(page, 'B1', '3');

    await page.reload();
    await expect(page.getByRole('grid', { name: 'Worksheet grid' })).toBeVisible();
    await expectCellText(page, 'A1', '3');
  });
});


